//! Tailwind CSS 4.3.2 default colors lowered to packed sRGB.
//!
//! The source values are the 286 `oklch(...)` declarations in
//! `package/theme.css` from the official `tailwindcss-4.3.2.tgz` npm artifact
//! (SHA-1 `408ee67d767a0fef7b174674bb9c5ce136a5ace1`). The table was generated by
//! converting OKLCH to OKLab, applying the CSS Color 4 OKLab-to-linear-sRGB
//! matrix and sRGB transfer function, clamping every encoded channel to
//! `[0, 1]`, and rounding to the nearest 8-bit channel.
//!
//! GPUI 0.2.2's packed `rgb(u32)` path cannot preserve an OKLCH color or a
//! wide-gamut component. Direct channel clamping is deterministic and cheap,
//! but a browser or another color-managed host may use a perceptual gamut
//! mapping algorithm or a wider output gamut and therefore render an
//! out-of-sRGB Tailwind color differently. Keeping the generated table here
//! makes native GPUI output stable and leaves no color conversion in either
//! macro-expanded code or the application render path.

/// Number of named shade steps in each Tailwind palette.
const SHADE_COUNT: usize = 11;

/// Number of default Tailwind 4.3.2 palette families.
const PALETTE_COUNT: usize = 26;

