/// Resolves one Tailwind color name to a packed `0xRRGGBB` sRGB value.
///
/// The accepted names are `black`, `white`, and every combination of the 26
/// Tailwind 4.3.2 default families with shades `50`, `100` through `900`, and
/// `950`. Parsing and lookup run only while expanding the view macro.
pub(super) fn rgb(name: &str) -> Option<u32> {
    match name {
        "black" => return Some(0x0000_0000),
        "white" => return Some(0x00ff_ffff),
        _ => {}
    }

    let (family, shade) = name.rsplit_once('-')?;
    Some(PALETTES[palette_index(family)?][shade_index(shade)?])
}

/// Maps an official Tailwind family name to its row in [`PALETTES`].
fn palette_index(family: &str) -> Option<usize> {
    Some(match family {
        "red" => 0,
        "orange" => 1,
        "amber" => 2,
        "yellow" => 3,
        "lime" => 4,
        "green" => 5,
        "emerald" => 6,
        "teal" => 7,
        "cyan" => 8,
        "sky" => 9,
        "blue" => 10,
        "indigo" => 11,
        "violet" => 12,
        "purple" => 13,
        "fuchsia" => 14,
        "pink" => 15,
        "rose" => 16,
        "slate" => 17,
        "gray" => 18,
        "zinc" => 19,
        "neutral" => 20,
        "stone" => 21,
        "mauve" => 22,
        "olive" => 23,
        "mist" => 24,
        "taupe" => 25,
        _ => return None,
    })
}

/// Maps a Tailwind shade suffix to its column in [`PALETTES`].
fn shade_index(shade: &str) -> Option<usize> {
    Some(match shade {
        "50" => 0,
        "100" => 1,
        "200" => 2,
        "300" => 3,
        "400" => 4,
        "500" => 5,
        "600" => 6,
        "700" => 7,
        "800" => 8,
        "900" => 9,
        "950" => 10,
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    //! Coverage for the generated Tailwind 4.3.2 color table.

    use super::*;

    /// Ensures every family exposes all eleven official shade steps.
    #[test]
    fn exposes_every_shade_of_every_palette() {
        for family in [
            "red", "orange", "amber", "yellow", "lime", "green", "emerald", "teal", "cyan", "sky",
            "blue", "indigo", "violet", "purple", "fuchsia", "pink", "rose", "slate", "gray",
            "zinc", "neutral", "stone", "mauve", "olive", "mist", "taupe",
        ] {
            for shade in [
                "50", "100", "200", "300", "400", "500", "600", "700", "800", "900", "950",
            ] {
                let name = format!("{family}-{shade}");
                assert!(rgb(&name).is_some(), "missing {name}");
            }
        }
    }

    /// Pins one generated midpoint from every official palette family.
    #[test]
    fn matches_representative_generated_values() {
        for (name, expected) in [
            ("red-500", 0x00fb_2c36),
            ("orange-500", 0x00ff_6900),
            ("amber-500", 0x00fe_9a00),
            ("yellow-500", 0x00f0_b100),
            ("lime-500", 0x007c_cf00),
            ("green-500", 0x0000_c950),
            ("emerald-500", 0x0000_bc7d),
            ("teal-500", 0x0000_bba7),
            ("cyan-500", 0x0000_b8db),
            ("sky-500", 0x0000_a6f4),
            ("blue-500", 0x002b_7fff),
            ("indigo-500", 0x0061_5fff),
            ("violet-500", 0x008e_51ff),
            ("purple-500", 0x00ad_46ff),
            ("fuchsia-500", 0x00e1_2afb),
            ("pink-500", 0x00f6_339a),
            ("rose-500", 0x00ff_2056),
            ("slate-500", 0x0062_748e),
            ("gray-500", 0x006a_7282),
            ("zinc-500", 0x0071_717b),
            ("neutral-500", 0x0073_7373),
            ("stone-500", 0x0079_716b),
            ("mauve-500", 0x0079_697b),
            ("olive-500", 0x007c_7c67),
            ("mist-500", 0x0067_787c),
            ("taupe-500", 0x007c_6d67),
        ] {
            assert_eq!(rgb(name), Some(expected), "mismatch for {name}");
        }
    }

    /// Handles singleton colors and rejects non-default names and shades.
    #[test]
    fn handles_singletons_and_invalid_names() {
        assert_eq!(rgb("black"), Some(0x0000_0000));
        assert_eq!(rgb("white"), Some(0x00ff_ffff));
        assert_eq!(rgb("red-0"), None);
        assert_eq!(rgb("brand-500"), None);
        assert_eq!(rgb("transparent"), None);
    }
}
